  function empty(title,text,action=""){return `<div class="finance-empty"><h2>${title}</h2><p>${text}</p>${action}</div>`;}
  function stats(includeAssets=false){const income=FinanceDomain.calculateMonthlyIncome(ui.transactions,month()),expense=FinanceDomain.calculateMonthlyExpense(ui.transactions,month()),payments=FinanceDomain.calculateMonthlyCreditCardPayments(ui.transactions,month()),net=income-expense,assets=FinanceDomain.calculateTotalAssets(ui.accounts,ui.transactions),liabilities=FinanceDomain.calculateTotalCreditCardLiabilities(ui.cards,ui.transactions),netWorth=FinanceDomain.calculateNetWorth(ui.accounts,ui.cards,ui.transactions);const items=includeAssets?[["總資產",assets,"wallet","全部帳戶"],["信用卡未繳",liabilities,"expense","卡片負債"],["淨資產",netWorth,netWorth<0?"expense":"balance","資產 − 卡片負債"],["本月收入",income,"income","↗ 收入"],["本月消費支出",expense,"expense","刷卡僅認列一次"],["本月卡費繳款",payments,"wallet","現金流，不重複算支出"],["本月結餘",net,net<0?"expense":"balance","收入 − 消費支出"]]:[["本月收入",income,"income","↗ 收入"],["本月消費支出",expense,"expense","不含卡費繳款"],["本月卡費繳款",payments,"wallet","獨立現金流"],["本月結餘",net,net<0?"expense":"balance","收入 − 消費支出"]];return `<div class="finance-stats ${includeAssets?"expanded":""}">${items.map(([label,value,kind,hint])=>`<article class="finance-kpi ${kind}"><div><small>${label}</small><span>${hint}</span></div><strong>${money(value)}</strong></article>`).join("")}</div>`;}
  function transactionLabel(row){const categories=mapById(ui.categories),accounts=mapById(ui.accounts),cards=mapById(ui.cards);if(row.type==="transfer")return {title:"帳戶轉帳",sub:`${accounts.get(row.fromAccountId)?.name||"歷史帳戶"} → ${accounts.get(row.toAccountId)?.name||"歷史帳戶"}`,account:""};if(row.type==="credit_card_purchase")return {title:categories.get(row.categoryId)?.name||"歷史分類",sub:row.note||"信用卡消費",account:cards.get(row.creditCardId)?.name||"歷史信用卡"};if(row.type==="credit_card_payment")return {title:"信用卡繳款",sub:row.note||cards.get(row.creditCardId)?.name||"歷史信用卡",account:accounts.get(row.fromAccountId||row.accountId)?.name||"歷史帳戶"};return {title:categories.get(row.categoryId)?.name||"歷史分類",sub:row.note||transactionTypes[row.type]||row.type,account:accounts.get(row.accountId)?.name||"歷史帳戶"};}
  function signedAmount(row){return row.type==="income"?`+${money(row.amount)}`:row.type==="transfer"?money(row.amount):`−${money(row.amount)}`;}
  function transactionRows(rows,compact=false){return `<div class="finance-transaction-list">${rows.map(row=>{const label=transactionLabel(row);return `<article class="finance-transaction-row"><span class="finance-transaction-icon ${row.type}" aria-hidden="true">${transactionIcons[row.type]||"•"}</span><time datetime="${esc(row.date)}">${esc(row.date.slice(5).replace('-','/'))}</time><div class="finance-transaction-main"><small>${esc(transactionTypes[row.type]||row.type)}</small><b>${esc(label.sub||label.title)}</b><span>${esc(label.title)}</span></div><span class="finance-account-name">${esc(label.account||"—")}</span><strong class="${row.type}">${signedAmount(row)}</strong>${compact?"":`<div class="finance-row-actions"><button class="finance-link" data-finance-action="edit-transaction" data-id="${esc(row.id)}">編輯</button><button class="finance-link danger" data-finance-action="delete-transaction" data-id="${esc(row.id)}">刪除</button></div>`}</article>`;}).join("")}</div>`;}
