  function aiStatusLabel(){if(ui.ai.status==="checking")return productionJobBridge?"檢查家中 AI 主機中":"檢查安全閘道中";if(ui.ai.status==="connected")return productionJobBridge?(ui.host.availability?.state==="busy"?"家中 AI 主機處理中":"家中 AI 主機在線"):"Finance AI Gateway 已連線";if(ui.ai.status==="stale")return"家中 AI 主機可能暫時休眠";if(ui.ai.status==="disconnected")return productionJobBridge?"家中 AI 主機離線":"安全閘道暫時不可用";return"尚未檢查";}
  function memoryResult(){const applied=ui.ai.phase3?.ruleResult?.memory?.applied||[];if(!applied.length)return"";return `<div class="finance-memory-chip"><strong>已套用確認規則</strong><span>${applied.map(item=>`${esc(item.field)}：${esc(item.value)}`).join(" · ")}</span><button type="button" data-finance-action="view-rule-memory">查看規則</button></div>`;}
  function aiResult(){const result=ui.ai.result,validation=ui.ai.validation;if(!result)return"";const committed=ui.ai.committed,status=committed?"已安全記帳":validation?.status==="ready"?(validation.commitEligible?"可以安全入帳":"需人工確認"):validation?.status==="blocked"?"已阻擋":"需要補充資料",canApply=result.valid&&validation?.status!=="blocked"&&!committed,canConfirm=validation?.status==="ready"&&validation.commitEligible&&!committed;return `<div class="finance-ai-result"><header><div><span>VALIDATED DRAFT</span><strong>${status}</strong></div><small>${committed?`正式交易 ${esc(committed.id||"")} 已建立`:ui.ai.dryRun?"安全檢查已通過，等待你的確認":"尚未寫入帳本"}</small></header>${memoryResult()}<dl><dt>類型</dt><dd>${esc(transactionTypes[result.draft.type]||result.draft.type||"未判定")}</dd><dt>金額</dt><dd>${result.draft.amount==null?"未判定":money(result.draft.amount)}</dd><dt>日期</dt><dd>${esc(result.draft.date||"未判定")}</dd><dt>分類</dt><dd>${esc(result.draft.category||"未判定")}</dd><dt>付款來源</dt><dd>${esc(result.draft.account||result.draft.creditCard||result.draft.fromAccount||"未判定")}</dd></dl>${draftResultList("需要補充",result.unresolved,"unresolved")}${draftResultList("名稱不明確",result.ambiguous,"ambiguous")}${draftResultList("安全驗證阻擋",validation?.invalidFields,"errors")}${draftResultList("安全驗證問題",validation?.issues,"unresolved")}${draftResultList("安全驗證警告",validation?.warnings,"warnings")}${draftResultList("Draft 驗證錯誤",result.errors,"errors")}${canApply||canConfirm?`<div class="finance-ai-result-actions">${canApply?`<button class="finance-button" data-finance-action="apply-ollama-draft">套用到記帳表單</button>`:""}${canConfirm?`<button class="finance-button primary" data-finance-action="confirm-ai-transaction" ${ui.ai.loading?"disabled":""}>確認記帳</button>`:""}</div>`:""}</div>`;}
  function advancedQueryResult(){
    const row=ui.advanced.query;if(!row)return"";if(!row.ok)return `<section class="finance-ledger-query" role="status"><small>唯讀帳本查詢</small><strong>需要你指定更明確的帳戶、信用卡或分類。</strong></section>`;
    const result=row.result||{},type=row.query.type;let answer="";
    if(type==="RECENT_TRANSACTIONS")answer=`最近 ${result.transactions.length} 筆交易`;
    else answer=`${result.entity?.name?`${result.entity.name}：`:""}${money(result.amount||0)}${result.count!=null?`（${result.count} 筆）`:""}`;
    return `<section class="finance-ledger-query" role="status"><small>唯讀帳本查詢 · 不會建立交易</small><strong>${esc(answer)}</strong>${row.warning?`<p>${esc(row.warning)}</p>`:""}${type==="RECENT_TRANSACTIONS"&&result.transactions.length?transactionRows(result.transactions,true):""}</section>`;
  }
  function candidatePaymentOptions(candidate){const value=candidate.draft.fromAccount||candidate.draft.account||candidate.draft.creditCard||"";return `<option value="">未指定</option><optgroup label="帳戶">${activeAccounts().map(row=>`<option value="account|${esc(row.name)}" ${value===row.name?"selected":""}>${esc(row.name)}</option>`).join("")}</optgroup><optgroup label="信用卡">${activeCards().map(row=>`<option value="creditCard|${esc(row.name)}" ${value===row.name?"selected":""}>${esc(row.name)}</option>`).join("")}</optgroup>`;}
  function advancedReviewBasket(){
    const candidates=advancedSession.list();if(!candidates.length)return"";const ready=candidates.filter(row=>row.status==="READY"&&row.validation?.commitEligible).length;
    return `<section class="finance-review-basket"><header><div><small>PHASE 10 · REVIEW BASKET</small><h3>逐筆確認候選交易</h3></div><div><button class="finance-button" data-finance-action="clear-advanced-session">清除暫存</button><button class="finance-button primary" data-finance-action="confirm-all-ready" ${ready&&!ui.advanced.busy?"":"disabled"}>確認全部 READY（${ready}）</button></div></header>${ui.advanced.message?`<p class="finance-advanced-message" role="status">${esc(ui.advanced.message)}</p>`:""}<div class="finance-review-list">${candidates.map((candidate,index)=>{const draft=candidate.draft||{},validation=candidate.validation||{},canConfirm=candidate.status==="READY"&&validation.commitEligible;return `<article class="finance-review-item ${candidate.status.toLowerCase()}" data-draft-id="${esc(candidate.draftId)}"><header><span>第 ${index+1} 筆</span><strong>${esc(candidate.status)}</strong></header><blockquote>${esc(candidate.rawText)}</blockquote><dl><dt>類型</dt><dd>${esc(transactionTypes[draft.type]||draft.type||"未判定")}</dd><dt>金額</dt><dd>${draft.amount==null?"未判定":money(draft.amount)}</dd><dt>日期</dt><dd>${esc(draft.date||"未判定")}</dd><dt>分類</dt><dd>${esc(draft.category||"未判定")}</dd><dt>付款來源</dt><dd>${esc(draft.account||draft.creditCard||draft.fromAccount||"未判定")}</dd></dl>${draftResultList("安全驗證阻擋",validation.invalidFields,"errors")}${draftResultList("需要補充",validation.issues,"unresolved")}<form data-finance-form="advanced-edit"><input type="hidden" name="draftId" value="${esc(candidate.draftId)}"><label>金額<input name="amount" inputmode="numeric" value="${esc(draft.amount??"")}" ${["COMMITTED","CANCELLED"].includes(candidate.status)?"disabled":""}></label><label>日期<input name="date" type="date" value="${esc(draft.date||"")}" ${["COMMITTED","CANCELLED"].includes(candidate.status)?"disabled":""}></label><label>付款來源<select name="payment" ${["COMMITTED","CANCELLED"].includes(candidate.status)?"disabled":""}>${candidatePaymentOptions(candidate)}</select></label><button class="finance-button" ${["COMMITTED","CANCELLED"].includes(candidate.status)?"disabled":""}>更新</button></form><footer><button class="finance-button danger" data-finance-action="cancel-advanced-draft" data-id="${esc(candidate.draftId)}" ${["COMMITTED","CANCELLED"].includes(candidate.status)?"disabled":""}>取消此筆</button><button class="finance-button primary" data-finance-action="confirm-advanced-draft" data-id="${esc(candidate.draftId)}" ${canConfirm&&!ui.advanced.busy?"":"disabled"}>確認記帳</button></footer></article>`;}).join("")}</div></section>`;
  }
  function aiQuickCard(){
    const bridge=productionJobBridge,unsupported="此瀏覽器不支援語音辨識，仍可使用文字輸入。";
    return `<section class="finance-section finance-ai-quick" data-finance-voice-root><div class="finance-section-head"><div><small>${bridge?"SUPABASE JOB BRIDGE · HOME AI":"LOCAL AI · SECURE GATEWAY"}</small><h2>AI 快速記帳</h2></div><span class="finance-ai-status ${ui.ai.status}" data-finance-host-status><i></i><span data-finance-host-status-text>${esc(aiStatusLabel())}</span></span></div><div class="finance-advanced-toggle"><div><strong>進階對話模式</strong><small>可一次整理多筆、修改、取消及唯讀查詢</small></div><button type="button" class="finance-button ${ui.advanced.enabled?"primary":""}" data-finance-action="toggle-advanced-mode" aria-pressed="${ui.advanced.enabled}">${ui.advanced.enabled?"已開啟":"開啟"}</button></div><p>${bridge?"輸入只會以短生命週期 AI Job 送往 Supabase，由家中已登入的 AI Host 取件並呼叫 localhost Gateway；結果回到此裝置後仍會經過安全驗證。":"輸入一段記帳文字。內容只會送到本機 Finance AI Gateway；完整且通過安全驗證的 Draft 才會進入既有記帳流程。"}</p><form data-finance-form="ai-quick"><div class="finance-ai-input"><label for="finance-ai-text">自然語言記帳</label><div class="finance-ai-input-row"><textarea id="finance-ai-text" name="aiText" rows="3" maxlength="300" placeholder="例如：早餐80現金，午餐120現金" ${ui.ai.loading||ui.advanced.busy?"disabled":""}>${esc(ui.ai.input)}</textarea><button type="button" class="finance-voice-button ${voiceActive()?"listening":""}" data-finance-action="toggle-voice" aria-pressed="${voiceActive()}" ${!ui.voice.supported||ui.ai.loading||ui.advanced.busy||ui.voice.status==="processing"?"disabled":""}>${voiceButtonLabel()}</button></div></div><p class="finance-voice-privacy">語音由瀏覽器辨識；本網站只接收辨識後文字，不保存音檔。語音說「全部確認」也不會自動入帳。</p><p class="finance-voice-unsupported" data-finance-voice-unsupported ${ui.voice.supported?"hidden":""}>${unsupported}</p><p class="finance-voice-interim" data-finance-voice-interim aria-live="polite" ${ui.voice.interim?"":"hidden"}>${ui.voice.interim?`${esc(`聽到：${ui.voice.interim}`)}`:""}</p><p class="finance-voice-error" data-finance-voice-error role="alert" ${ui.voice.error?"":"hidden"}>${esc(ui.voice.error)}</p><div class="finance-ai-meta"><span>傳輸：${bridge?"Supabase 工作佇列 → 家中 AI":"本機安全閘道"}${ui.ai.jobStatus?` · ${esc(ui.ai.jobStatus)}`:""}</span><div>${ui.ai.loading||ui.advanced.busy?`<button type="button" class="finance-button" data-finance-action="cancel-ai">取消等待</button><span class="finance-ai-loading"><i></i>正在整理並安全驗證交易……</span>`:`<button class="finance-button primary" data-finance-ai-submit ${voiceActive()?"disabled":""}>${ui.advanced.enabled?"整理指令":"AI 解析"}</button>`}</div></div></form>${ui.ai.error?`<div class="finance-ai-error" role="alert">${esc(ui.ai.error)}</div>`:""}${ui.advanced.enabled?`${advancedQueryResult()}${advancedReviewBasket()}`:aiResult()}</section>`;
  }
  function aiHostCard(){if(!aiHostMode)return"";const state=ui.host.state||{},status=state.busy?"處理中":state.paused?"已暫停":state.active?"在線":"離線",recent=state.lastCompleted;return `<section class="finance-section finance-ai-host-card"><div class="finance-section-head"><div><small>BROWSER AI HOST · PHASE 6B</small><h2>家中 AI 主機</h2></div><span class="finance-ai-status ${state.active?"connected":"disconnected"}"><i></i>${esc(status)}</span></div><div class="finance-host-grid"><div><small>Host ID</small><strong>${esc(state.hostId||"初始化中")}</strong></div><div><small>目前工作</small><strong>${esc(state.currentJob?.request_id||"待命")}</strong></div><div><small>最近結果</small><strong>${esc(recent?`${recent.status} · ${recent.requestId||recent.id}`:"尚無")}</strong></div></div>${ui.host.error?`<div class="finance-ai-error" role="alert">${esc(ui.host.error)}</div>`:""}<div class="finance-actions"><button class="finance-button" data-finance-action="host-health">立即健康檢查</button><button class="finance-button primary" data-finance-action="${state.paused?"host-resume":"host-pause"}" ${state.active?"":"disabled"}>${state.paused?"恢復取件":"暫停取件"}</button></div><p>此分頁只從 Supabase 取得你自己的短期 AI Job，並只呼叫 <code>127.0.0.1:4181</code>。請保持分頁開啟。</p></section>`;}
  function trendCard(){const months=FinanceUiModel.recentMonths(6),trend=FinanceDomain.summarizeMonthlyTrend(ui.transactions,months),max=Math.max(1,...trend.flatMap(row=>[row.income,row.expense]));return `<section class="finance-section finance-chart-card"><div class="finance-section-head"><div><small>6 MONTHS</small><h2>收支趨勢</h2></div><button class="finance-link" data-finance-view="reports">完整報表 →</button></div><div class="finance-dashboard-trend">${trend.map(row=>`<div><span>${esc(row.month.slice(5))}月</span><div><i class="income" style="height:${Math.max(3,row.income/max*100)}%"></i><i class="expense" style="height:${Math.max(3,row.expense/max*100)}%"></i></div><small>${money(row.income)}<br>${money(row.expense)}</small></div>`).join("")}</div><div class="finance-chart-legend"><span><i class="income"></i>收入</span><span><i class="expense"></i>支出</span></div></section>`;}
  function categoryCard(){const range=FinanceUiModel.monthRange(0),rows=FinanceDomain.summarizeExpensesByCategory(ui.transactions,range.start,range.end),categories=mapById(ui.categories),total=rows.reduce((sum,row)=>sum+row.amount,0),colors=['#44d6a1','#64a8ff','#ffad5c','#df79d6','#f16f73','#a2a8bd'];return `<section class="finance-section finance-category-card"><div class="finance-section-head"><div><small>THIS MONTH</small><h2>支出分類</h2></div><button class="finance-link" data-finance-view="reports">查看分析 →</button></div>${rows.length?`<div class="finance-donut-wrap"><div class="finance-donut" style="background:conic-gradient(${rows.slice(0,6).map((row,index)=>{const before=rows.slice(0,index).reduce((sum,item)=>sum+item.amount,0)/total*100,after=(before+row.amount/total*100);return `${colors[index%colors.length]} ${before}% ${after}%`;}).join(',')})"><strong>${money(total)}<small>本月支出</small></strong></div><div class="finance-category-legend">${rows.slice(0,6).map((row,index)=>`<div><i style="background:${colors[index]}"></i><span>${esc(categories.get(row.categoryId)?.name||'歷史分類')}<small>${Math.round(row.amount/total*100)}%</small></span><strong>${money(row.amount)}</strong></div>`).join('')}</div></div>`:empty("本月尚無支出","開始記帳後顯示分類分析。")}</section>`;}
  function overview(){const recent=FinanceUiModel.sortTransactions(ui.transactions).slice(0,6);return `<div class="finance-dashboard">${aiHostCard()}${stats(true)}${quickActions()}${aiQuickCard()}<div class="finance-dashboard-main">${trendCard()}${categoryCard()}</div><div class="finance-dashboard-lower"><section class="finance-section finance-recent"><div class="finance-section-head"><div><small>LATEST ACTIVITY</small><h2>最近交易</h2></div><button class="finance-link" data-finance-view="transactions">查看全部 →</button></div>${recent.length?transactionRows(recent,true):empty("目前沒有交易","新增收入、支出或轉帳。")}</section><aside class="finance-dashboard-side"><section class="finance-section"><div class="finance-section-head"><h2>帳戶餘額</h2><button class="finance-link" data-finance-view="accounts">管理 →</button></div>${activeAccounts().length?`<div class="finance-balance-list">${activeAccounts().slice(0,5).map(row=>`<button data-finance-view="accounts"><i>${esc((accountTypes[row.type]||'帳').slice(0,1))}</i><span>${esc(row.name)}<small>${esc(accountTypes[row.type]||row.type)}</small></span><strong>${money(balance(row))}</strong></button>`).join('')}</div>`:empty("還沒有帳戶","先建立帳戶。")}</section><section class="finance-section"><div class="finance-section-head"><h2>信用卡</h2><button class="finance-link" data-finance-view="cards">管理 →</button></div>${activeCards().length?`<div class="finance-card-mini-list">${activeCards().slice(0,4).map(card=>`<button data-finance-view="cards"><span>${esc(card.name)}<small>${esc(card.bankName||'信用卡')} ${card.last4?`•••• ${esc(card.last4)}`:''}</small></span><strong><small>目前未繳</small>${money(outstanding(card))}</strong></button>`).join('')}</div>`:empty("還沒有信用卡","新增後顯示目前未繳。")}</section></aside></div></div>`;}
  function accountForm(){const row=ui.edit?.id?byId(ui.accounts,ui.edit.id):null;return `<form class="finance-form-card" data-finance-form="account" novalidate><div class="finance-form-head"><div><span>${row?"編輯帳戶":"新增帳戶"}</span><h2>${esc(row?.name||"建立帳戶")}</h2></div><button type="button" class="finance-link" data-finance-action="cancel-edit">取消</button></div><div class="finance-form-grid">${field("name","帳戶名稱",`<input name="name" required maxlength="60" value="${esc(row?.name||"")}">`)}${field("type","帳戶類型",`<select name="type">${Object.entries(accountTypes).map(([value,label])=>`<option value="${value}" ${row?.type===value?"selected":""}>${label}</option>`).join("")}</select>`)}${field("bankName","金融機構（選填）",`<input name="bankName" maxlength="60" value="${esc(row?.bankName||"")}">`,false)}${field("last4","帳號末四碼（選填）",`<input name="last4" inputmode="numeric" maxlength="4" value="${esc(row?.last4||"")}">`)}${field("initialBalance",`初始餘額（${esc(setting("baseCurrency","TWD"))}）`,`<input name="initialBalance" inputmode="numeric" required value="${esc(row?.initialBalance??"")}">`)}<label class="finance-checkbox"><input type="checkbox" name="includeInAssets" ${row?.includeInAssets===false?"":"checked"}> 納入總資產</label></div><footer><button type="button" class="finance-button" data-finance-action="cancel-edit">取消</button><button class="finance-button primary">儲存帳戶</button></footer></form>`;}
  function accountsPage(){return `${pageHead("帳戶","我的帳戶",`<button class="finance-button primary" data-finance-action="new-account">＋ 新增帳戶</button>`)}${ui.edit?.kind==="account"?accountForm():ui.accounts.length?accountCards():empty("還沒有帳戶","先建立第一個帳戶。")}`;}
  function cardForm(){const row=ui.edit?.id?byId(ui.cards,ui.edit.id):null;return `<form class="finance-form-card" data-finance-form="card" novalidate><div class="finance-form-head"><div><span>${row?"編輯信用卡":"新增信用卡"}</span><h2>${esc(row?.name||"建立信用卡")}</h2></div><button type="button" class="finance-link" data-finance-action="cancel-edit">取消</button></div><div class="finance-form-grid">${field("name","卡片名稱",`<input name="name" required maxlength="60" value="${esc(row?.name||"")}">`)}${field("bankName","銀行／發卡機構",`<input name="bankName" maxlength="60" value="${esc(row?.bankName||"")}">`,false)}${field("last4","卡號末四碼",`<input name="last4" inputmode="numeric" maxlength="4" value="${esc(row?.last4||"")}">`)}${field("creditLimit","信用額度（只供參考）",`<input name="creditLimit" inputmode="numeric" value="${esc(row?.creditLimit??0)}">`)}${field("closingDay","結帳日",`<input name="closingDay" type="number" min="1" max="31" value="${esc(row?.closingDay??1)}">`)}${field("dueDay","繳款日",`<input name="dueDay" type="number" min="1" max="31" value="${esc(row?.dueDay??15)}">`)}${field("linkedPaymentAccountId","預設付款帳戶",`<select name="linkedPaymentAccountId">${options(activeAccounts(),row?.linkedPaymentAccountId,"name","不指定")}</select>`)}</div><footer><button type="button" class="finance-button" data-finance-action="cancel-edit">取消</button><button class="finance-button primary">儲存信用卡</button></footer></form>`;}
  function cardsPage(){return `${pageHead("信用卡","信用卡與目前未繳",`<div class="finance-actions"><button class="finance-button" data-finance-action="new-card-payment" ${activeCards().length&&activeAccounts().length?"":"disabled"}>繳卡費</button><button class="finance-button" data-finance-action="new-card-purchase" ${activeCards().length?"":"disabled"}>記刷卡</button><button class="finance-button primary" data-finance-action="new-card">＋ 新增信用卡</button></div>`)}<p class="finance-help">「目前未繳」依本機 Ledger 的信用卡消費減繳款計算，不代表銀行正式帳單金額。</p>${ui.edit?.kind==="card"?cardForm():ui.cards.length?cardCards():empty("還沒有信用卡","新增信用卡後可記錄消費與繳款。")}`;}
  function categoryForm(){const row=ui.edit?.id?byId(ui.categories,ui.edit.id):null;return `<form class="finance-form-card" data-finance-form="category" novalidate><div class="finance-form-head"><div><span>${row?"編輯分類":"新增分類"}</span><h2>${esc(row?.name||"建立分類")}</h2></div><button type="button" class="finance-link" data-finance-action="cancel-edit">取消</button></div><div class="finance-form-grid">${field("name","分類名稱",`<input name="name" maxlength="40" value="${esc(row?.name||"")}">`)}${field("type","分類類型",`<select name="type" ${row?.system?"disabled":""}><option value="expense" ${row?.type!=="income"?"selected":""}>支出</option><option value="income" ${row?.type==="income"?"selected":""}>收入</option></select>${row?.system?`<input type="hidden" name="type" value="${esc(row.type)}">`:""}`)}${field("icon","短圖示（選填）",`<input name="icon" maxlength="2" value="${esc(row?.icon||"")}">`,false)}</div><footer><button type="button" class="finance-button" data-finance-action="cancel-edit">取消</button><button class="finance-button primary">儲存分類</button></footer></form>`;}
  function categoryGroup(type,title){const rows=ui.categories.filter(row=>row.type===type);return `<section class="finance-section"><h2>${title}</h2><div class="finance-category-grid">${rows.map(row=>`<article class="finance-category-item ${row.archived?"archived":""}"><span>${esc(row.icon||"類")}</span><div><b>${esc(row.name)}</b><small>${row.system?"系統分類":"自訂分類"}${row.archived?" · 已封存":""}</small></div><button class="finance-link" data-finance-action="edit-category" data-id="${esc(row.id)}">編輯</button>${row.archived?"":`<button class="finance-link danger" data-finance-action="archive-category" data-id="${esc(row.id)}">封存</button>`}</article>`).join("")}</div></section>`;}
  function categoriesPage(){return `${pageHead("分類","收入與支出分類",`<button class="finance-button primary" data-finance-action="new-category">＋ 新增分類</button>`)}${ui.edit?.kind==="category"?categoryForm():`${categoryGroup("expense","支出分類")}${categoryGroup("income","收入分類")}`}`;}
  function transactionFilters(){return `<form class="finance-filter" data-finance-form="filter"><select name="period" aria-label="日期篩選"><option value="month" ${ui.filters.period==="month"?"selected":""}>本月</option><option value="previous" ${ui.filters.period==="previous"?"selected":""}>上月</option><option value="custom" ${ui.filters.period==="custom"?"selected":""}>自訂日期</option></select><input type="date" name="start" aria-label="開始日期" value="${esc(ui.filters.start)}" ${ui.filters.period!=="custom"?"hidden":""}><input type="date" name="end" aria-label="結束日期" value="${esc(ui.filters.end)}" ${ui.filters.period!=="custom"?"hidden":""}><select name="type" aria-label="類型篩選"><option value="">全部類型</option>${Object.entries(transactionTypes).map(([value,label])=>`<option value="${value}" ${ui.filters.type===value?"selected":""}>${label}</option>`).join("")}</select><input type="search" name="query" value="${esc(ui.filters.query)}" placeholder="搜尋備註、分類、帳戶" aria-label="搜尋交易"><button class="finance-button">套用</button></form>`;}
  function aiDraftBanner(){if(!ui.aiDraftApplied)return"";return `<section class="finance-ai-draft-banner" role="status"><div><span>✦ DRAFT 建議</span><strong>尚未寫入帳本，請確認後再記帳。</strong><small>來源：${esc(ui.aiDraftApplied.source||"unknown")} · 你可以直接修改下方欄位。</small></div><div><button type="button" class="finance-button" data-finance-action="focus-draft-form">修改</button><button type="button" class="finance-button" data-finance-action="clear-ai-draft">清除 Draft</button></div></section>`;}
  function transactionForm(){const existing=ui.edit?.id?byId(ui.transactions,ui.edit.id):null,row=ui.draft||existing||{type:"expense",date:FinanceUiModel.localDate(),amount:"",note:""},type=row.type||"expense",withHistorical=(activeRows,allRows,id)=>id&&!activeRows.some(item=>item.id===id)&&byId(allRows,id)?[byId(allRows,id),...activeRows]:activeRows,accounts=withHistorical(activeAccounts(),ui.accounts,row.accountId||row.fromAccountId||row.toAccountId),cards=withHistorical(activeCards(),ui.cards,row.creditCardId),categories=withHistorical(activeCategories(type==="income"?"income":"expense"),ui.categories,row.categoryId);let refs="";if(["income","expense"].includes(type))refs=`${field("categoryId","分類",`<select name="categoryId">${options(categories,row.categoryId,item=>`${item.name}${item.archived?"（已封存）":""}`)}</select>`)}${field("accountId",type==="income"?"入帳帳戶":"付款帳戶",`<select name="accountId">${options(accounts,row.accountId,item=>`${item.name}${item.archived?"（已封存）":""}`)}</select>`)}`;if(type==="transfer"){const fromAccounts=withHistorical(activeAccounts(),ui.accounts,row.fromAccountId),toAccounts=withHistorical(activeAccounts(),ui.accounts,row.toAccountId);refs=`${field("fromAccountId","轉出帳戶",`<select name="fromAccountId">${options(fromAccounts,row.fromAccountId,item=>`${item.name}${item.archived?"（已封存）":""}`)}</select>`)}${field("toAccountId","轉入帳戶",`<select name="toAccountId">${options(toAccounts,row.toAccountId,item=>`${item.name}${item.archived?"（已封存）":""}`)}</select>`)}`;}if(type==="credit_card_purchase")refs=`${field("creditCardId","信用卡",`<select name="creditCardId">${options(cards,row.creditCardId,item=>`${item.name}${item.archived?"（已封存）":""}`)}</select>`)}${field("categoryId","支出分類",`<select name="categoryId">${options(categories,row.categoryId,item=>`${item.name}${item.archived?"（已封存）":""}`)}</select>`)}`;if(type==="credit_card_payment")refs=`${field("fromAccountId","付款帳戶",`<select name="fromAccountId">${options(accounts,row.fromAccountId||row.accountId,item=>`${item.name}${item.archived?"（已封存）":""}`)}</select>`)}${field("creditCardId","信用卡",`<select name="creditCardId">${options(cards,row.creditCardId,item=>`${item.name}${item.archived?"（已封存）":""}`)}</select>`)}`;return `${aiDraftBanner()}<form class="finance-form-card" data-finance-form="transaction" novalidate><div class="finance-form-head"><div><span>${existing?"修改交易":"新增交易"}</span><h2>${transactionTypes[type]||"記帳"}</h2></div><button type="button" class="finance-link" data-finance-action="cancel-edit">取消</button></div><div class="finance-type-switch five" role="group" aria-label="交易類型">${Object.entries(transactionTypes).map(([value,label])=>`<label><input type="radio" name="type" value="${value}" ${type===value?"checked":""}>${label}</label>`).join("")}</div><div class="finance-form-grid">${field("date","日期",`<input type="date" name="date" value="${esc(row.date||FinanceUiModel.localDate())}">`)}${field("amount",`金額（${esc(setting("baseCurrency","TWD"))}）`,`<input name="amount" inputmode="numeric" value="${esc(row.amount??"")}">`)}${refs}${type==="credit_card_payment"?`<p class="finance-help finance-wide">信用卡繳款只會扣除付款帳戶並降低卡片未繳，不會再次列入支出或支出分類。</p>`:""}<label class="finance-wide">備註（選填）<textarea name="note" maxlength="200" rows="3">${esc(row.note||"")}</textarea></label></div><footer><button type="button" class="finance-button" data-finance-action="cancel-edit">取消</button><button class="finance-button primary">預覽確認</button></footer></form>`;}
  function draftResultList(title,rows,kind){if(!rows?.length)return"";return `<section class="${kind}"><h4>${title}</h4><ul>${rows.map(row=>`<li><b>${esc(row.field||row.code||"")}</b> ${esc(row.value??"")}<span>${esc(row.message||"")}</span></li>`).join("")}</ul></section>`;}
  function draftTestPanel(){if(!draftTestEnabled)return"";const result=ui.draftTestResult,validation=ui.draftTestValidation,dryRun=ui.draftTestDryRun,canApply=result?.valid&&validation?.status!=="blocked";return `<details class="finance-draft-test" open><summary><span>✦ Finance Phase 4 Dry Run</span><small>安全驗證 · 不會寫入帳本</small></summary><form data-finance-form="draft-test" novalidate><label>貼入 JSON Draft<textarea name="draftJson" rows="12" spellcheck="false">${esc(ui.draftTestInput)}</textarea></label><div class="finance-actions"><button class="finance-button primary">驗證 Draft</button>${canApply?`<button type="button" class="finance-button" data-finance-action="apply-ai-draft">套用到記帳表單</button>`:""}</div></form>${ui.draftTestError?`<div class="finance-draft-test-error" role="alert">${esc(ui.draftTestError)}</div>`:""}${result?`<div class="finance-draft-result"><header><strong>${validation?.status==="ready"?"READY":validation?.status==="blocked"?"BLOCKED":"NEEDS INPUT"}</strong><span>${dryRun?"Payload 已建立，交易筆數不變":validation?.status==="ready"?"含警告，保留人工確認":"請處理缺漏或阻擋原因"}</span></header><section><h4>Normalized Draft</h4><pre>${esc(JSON.stringify(result.draft,null,2))}</pre></section><section><h4>Resolved References</h4><pre>${esc(JSON.stringify(validation?.resolved||{},null,2))}</pre></section>${dryRun?`<section><h4>Dry-run Commit Payload</h4><pre>${esc(JSON.stringify(dryRun.payload,null,2))}</pre></section>`:""}${draftResultList("Missing",(validation?.missingFields||[]).map(field=>({field,message:"需要補充"})),"unresolved")}${draftResultList("Invalid",validation?.invalidFields,"errors")}${draftResultList("Issues",validation?.issues,"unresolved")}${draftResultList("Warnings",validation?.warnings,"warnings")}${draftResultList("Adapter Errors",result.errors,"errors")}</div>`:""}</details>`;}
  function transactionsPage(){const lookups={accounts:mapById(ui.accounts),cards:mapById(ui.cards),categories:mapById(ui.categories)},rows=FinanceUiModel.filterTransactions(ui.transactions,ui.filters,lookups);return `${pageHead("記帳","交易紀錄",`<button class="finance-button primary" data-finance-action="new-transaction" ${activeAccounts().length?"":"disabled"}>＋ 新增記帳</button>`)}${draftTestPanel()}${ui.edit?.kind==="transaction"?transactionForm():`${transactionFilters()}${rows.length?transactionRows(rows):empty("沒有符合條件的交易","調整日期、類型或搜尋條件。")}`}`;}
  function reportsPage(){const range=FinanceUiModel.monthRange(0),cardPayments=FinanceDomain.calculateMonthlyCreditCardPayments(ui.transactions,month()),categories=mapById(ui.categories),categoryRows=FinanceDomain.summarizeExpensesByCategory(ui.transactions,range.start,range.end),months=FinanceUiModel.recentMonths(6),trend=FinanceDomain.summarizeMonthlyTrend(ui.transactions,months),max=Math.max(1,...trend.flatMap(row=>[row.income,row.expense]));return `${pageHead("報表","基本財務報表")}${stats()}<section class="finance-section"><h2>本月卡費繳款</h2><p class="finance-help">${money(cardPayments)}｜屬付款帳戶現金流，不併入本月消費支出與分類支出。</p></section><div class="finance-report-grid"><section class="finance-section"><h2>本月各分類支出</h2>${categoryRows.length?`<div class="finance-bars">${categoryRows.map(row=>`<div><span>${esc(categories.get(row.categoryId)?.name||"歷史分類")}</span><i style="--value:${Math.max(2,row.amount/Math.max(1,categoryRows[0].amount)*100)}%"></i><strong>${money(row.amount)}</strong></div>`).join("")}</div>`:empty("本月尚無支出","新增支出後顯示分類統計。")}</section><section class="finance-section"><h2>各帳戶餘額</h2><div class="finance-summary-list">${ui.accounts.map(row=>`<div><span>${esc(row.name)}${row.archived?"（已封存）":""}</span><strong>${money(balance(row))}</strong></div>`).join("")}</div></section></div><section class="finance-section"><h2>最近六個月收支趨勢</h2><div class="finance-trend">${trend.map(row=>`<div><span>${esc(row.month)}</span><div title="收入 ${money(row.income)}"><i class="income" style="height:${Math.max(2,row.income/max*100)}%"></i></div><div title="支出 ${money(row.expense)}"><i class="expense" style="height:${Math.max(2,row.expense/max*100)}%"></i></div><small>收 ${money(row.income)}<br>支 ${money(row.expense)}</small></div>`).join("")}</div></section>`;}
  function importPreview(){if(!ui.importPreview)return"";const preview=ui.importPreview;return `<section class="finance-import-preview ${preview.valid?"valid":"invalid"}"><h3>${preview.valid?"備份可讀取（僅預覽）":"備份無法匯入"}</h3>${preview.valid?`<div class="finance-summary-list">${FinanceBackup.COLLECTIONS.map(name=>`<div><span>${esc(name)}</span><strong>${preview.counts[name]}</strong></div>`).join("")}</div><p>本階段未開放 Restore；目前資料不會被覆寫。</p>`:`<ul>${preview.errors.slice(0,10).map(item=>`<li>${esc(item.message)}</li>`).join("")}</ul>`}${preview.warnings?.length?`<p>${preview.warnings.map(item=>esc(item.message)).join("；")}</p>`:""}</section>`;}
  function backgroundsPanel(){const active=ui.backgrounds.find(row=>row.active),prefs=backgroundPrefs();return `<section class="finance-section finance-background-summary"><div><small>APPEARANCE</small><h2>Finance 背景</h2><p>${active?`目前使用：${esc(active.name)}`:`內建主題：${esc(builtInBackgrounds.find(row=>row.id===prefs.theme)?.name||'極光湖泊')}`}。圖片只保存在本機，不包含在 JSON 備份。</p></div><button class="finance-button primary" data-finance-action="open-backgrounds">▧ 管理背景</button></section>`;}
  function backgroundModal(){const active=ui.backgrounds.find(row=>row.active),prefs=backgroundPrefs();return `<div class="finance-modal-backdrop finance-background-backdrop" data-finance-modal-backdrop><section class="finance-modal finance-background-modal" role="dialog" aria-modal="true" aria-labelledby="finance-background-title"><header><div><span>APPEARANCE</span><h2 id="finance-background-title" tabindex="-1" autofocus>背景設定</h2><p>選擇內建氛圍、管理本機圖片與調整閱讀對比。</p></div><button class="finance-modal-close" data-finance-action="close-modal" aria-label="關閉背景設定">×</button></header><div class="finance-background-scroll"><section><div class="finance-background-title"><h3>內建圖片</h3><small>使用 CSS 漸層，不需網路連線</small></div><div class="finance-background-grid built-in">${builtInBackgrounds.map(row=>`<button class="finance-background-choice theme-${row.className} ${!active&&prefs.theme===row.id?'active':''}" data-finance-action="select-built-in" data-theme="${row.id}" aria-pressed="${!active&&prefs.theme===row.id}"><i>${!active&&prefs.theme===row.id?'✓':''}</i><span>${esc(row.name)}${!active&&prefs.theme===row.id?'<small>目前使用</small>':''}</span></button>`).join('')}</div></section><section><div class="finance-background-title"><h3>我的圖片</h3><label class="finance-button primary">＋ 上傳圖片<input type="file" data-finance-background-input accept="image/png,image/jpeg,image/webp" hidden></label></div><p class="finance-background-help">支援 PNG、JPG、JPEG、WEBP，最大 10 MB。圖片 Blob 僅儲存在此裝置。</p><div class="finance-background-grid user">${ui.backgrounds.length?ui.backgrounds.map(row=>`<article class="finance-background-tile ${row.active?'active':''}"><button class="finance-background-choice" data-finance-action="select-background" data-id="${esc(row.id)}" aria-pressed="${row.active}" style="--thumb:url('${esc(ui.backgroundUrls.get(row.id)||'')}')"><i>${row.active?'✓':''}</i><span>${esc(row.name)}${row.active?'<small>目前使用</small>':''}</span></button><button class="finance-background-delete" data-finance-action="delete-background" data-id="${esc(row.id)}" aria-label="刪除背景 ${esc(row.name)}">刪除</button></article>`).join(''):empty("還沒有上傳圖片","你可以加入自己的生活照片作為背景。")}</div></section><section><div class="finance-background-title"><h3>純色主題與顯示</h3></div><form class="finance-display-settings" data-finance-form="background-settings"><fieldset><legend>背景模糊</legend><label><input type="radio" name="blur" value="false" ${prefs.blur?'':'checked'}> 關閉</label><label><input type="radio" name="blur" value="true" ${prefs.blur?'checked':''}> 開啟</label></fieldset><fieldset><legend>背景遮罩強度</legend>${[['weak','弱'],['medium','中'],['strong','強']].map(([value,label])=>`<label><input type="radio" name="overlay" value="${value}" ${prefs.overlay===value?'checked':''}> ${label}</label>`).join('')}</fieldset><button class="finance-button primary">套用顯示設定</button></form></section></div><footer><button class="finance-button" data-finance-action="default-background">恢復預設背景</button><button class="finance-button primary" data-finance-action="close-modal">完成</button></footer></section></div>`;}
  function aiSettingsCard(){if(productionJobBridge)return `<section class="finance-section finance-ai-settings"><div class="finance-section-head"><div><small>SUPABASE AI JOB BRIDGE</small><h2>AI 快速記帳連線</h2></div><span class="finance-ai-status ${ui.ai.status}" data-finance-host-status><i></i><span data-finance-host-status-text>${esc(aiStatusLabel())}</span></span></div><p>正式網站固定使用 Supabase Job Bridge，不接受任意遠端 Gateway URL，也不會直接連線 Ollama。家中 AI Host 只呼叫本機 <code>127.0.0.1:4181</code>。</p><footer><button type="button" class="finance-button" data-finance-action="launch-ai-host">開啟／重新檢查主機</button></footer></section>`;const config=aiSettings();return `<section class="finance-section finance-ai-settings"><div class="finance-section-head"><div><small>LOCAL AI GATEWAY</small><h2>AI 快速記帳設定</h2></div><span class="finance-ai-status ${ui.ai.status}"><i></i>${esc(aiStatusLabel())}</span></div><form data-finance-form="ai-settings"><div class="finance-form-grid">${field("provider","Provider",`<input name="provider" value="Finance AI Gateway" disabled>`,false)}${field("baseUrl","Gateway URL",`<input name="baseUrl" inputmode="url" value="${esc(config.baseUrl)}">`)}${field("timeout","Timeout（毫秒）",`<input name="timeout" type="number" min="1000" max="60000" step="1000" value="${esc(config.timeout)}">`)}</div><footer><button type="button" class="finance-button" data-finance-action="test-ollama">測試安全閘道</button><button class="finance-button primary">儲存 AI 設定</button></footer></form><p>瀏覽器不會直接連線 Ollama，也不能指定模型或 Prompt。只傳送目前輸入與解析所需的最小 active 名稱資料。</p></section>`;}
  const memoryFieldLabels={category:"分類",account:"帳戶",creditCard:"信用卡",merchant:"商家"},memoryMatchLabels={merchant:"商家完全相符",keyword:"包含關鍵字",phrase:"包含詞句"};
  function ruleMemoryPanel(){const rows=ui.ruleMemory.rules;return `<section class="finance-section finance-memory-panel" id="finance-rule-memory"><div class="finance-section-head"><div><small>PHASE 9 · USER-CONFIRMED ONLY</small><h2>已確認規則</h2></div><span class="finance-memory-state">${productionJobBridge?(ui.ruleMemory.state==="syncing"?"同步中":"本機優先同步"):"僅此裝置"}</span></div><p>規則只在你明確儲存後生效，只補分類、帳戶、信用卡或商家；金額與日期永遠不會被記憶。</p><div class="finance-actions"><button class="finance-button primary" data-finance-action="open-rule-memory">＋ 新增已確認規則</button>${productionJobBridge?`<button class="finance-button" data-finance-action="sync-rule-memory">同步規則</button>`:""}</div>${ui.ruleMemory.error?`<div class="finance-ai-error" role="alert">${esc(ui.ruleMemory.error)}</div>`:""}${rows.length?`<div class="finance-memory-list">${rows.map(row=>`<article class="finance-memory-row ${row.enabled?"":"disabled"}"><div><small>${esc(memoryMatchLabels[row.matchKind]||row.matchKind)}${row.scopeType?` · ${esc(transactionTypes[row.scopeType]||row.scopeType)}`:" · 所有類型"}</small><strong>${esc(row.matchValue)}</strong><span>→ ${esc(memoryFieldLabels[row.targetField]||row.targetField)}：${esc(row.targetLabelSnapshot)}</span></div><div><button class="finance-link" data-finance-action="toggle-rule-memory" data-id="${esc(row.id)}">${row.enabled?"停用":"啟用"}</button><button class="finance-link" data-finance-action="edit-rule-memory" data-id="${esc(row.id)}">編輯</button><button class="finance-link danger" data-finance-action="delete-rule-memory" data-id="${esc(row.id)}">刪除</button></div></article>`).join("")}</div>`:empty("尚無已確認規則","系統不會從交易歷史自動學習；請由你明確新增。")}</section>`;}
  function ruleTargetOptions(rule){const selected=!rule?.targetField?"":rule.targetField!=="merchant"?`${rule.targetField}|${rule.targetEntityId||""}`:"merchant|";const group=(label,fieldName,rows)=>`<optgroup label="${label}">${rows.map(row=>{const value=`${fieldName}|${row.id}`;return `<option value="${esc(value)}" ${selected===value?"selected":""}>${esc(row.name)}</option>`;}).join("")}</optgroup>`;return `<option value="" ${selected?"":"selected"}>請選擇</option>${group("分類","category",activeCategories())}${group("帳戶","account",activeAccounts())}${group("信用卡","creditCard",activeCards())}<option value="merchant|" ${selected==="merchant|"?"selected":""}>商家名稱（使用下方名稱）</option>`;}
  function ruleMemoryModal(){const row=ui.modal?.row||{},editing=Boolean(row.id);return `<div class="finance-modal-backdrop"><section class="finance-modal finance-memory-modal" role="dialog" aria-modal="true" aria-labelledby="finance-memory-title"><span>USER-CONFIRMED RULE</span><h2 id="finance-memory-title">${editing?"編輯":"新增"}已確認規則</h2><p>只有按下「確認儲存」才會建立規則；系統不會自動學習。</p><form data-finance-form="rule-memory"><input type="hidden" name="id" value="${esc(row.id||"")}"><div class="finance-form-grid">${field("matchKind","符合方式",`<select name="matchKind"><option value="keyword" ${row.matchKind==="keyword"||!row.matchKind?"selected":""}>包含關鍵字</option><option value="phrase" ${row.matchKind==="phrase"?"selected":""}>包含詞句</option><option value="merchant" ${row.matchKind==="merchant"?"selected":""}>商家完全相符</option></select>`)}${field("matchValue","觸發文字",`<input name="matchValue" maxlength="120" required value="${esc(row.matchValue||"")}" placeholder="例如：公司午餐">`)}${field("scopeType","適用交易類型",`<select name="scopeType"><option value="">所有類型</option>${Object.entries(transactionTypes).map(([value,label])=>`<option value="${value}" ${row.scopeType===value?"selected":""}>${label}</option>`).join("")}</select>`)}${field("target","要補上的資料",`<select name="target" required>${ruleTargetOptions(row)}</select>`)}${field("targetLabel","商家名稱（只在目標選商家時使用）",`<input name="targetLabel" maxlength="120" value="${esc(row.targetField==="merchant"?row.targetLabelSnapshot:"")}" placeholder="例如：中油">`)}</div><p class="finance-memory-confirm">確認：這項規則只補缺少欄位，不會覆蓋你輸入的內容，也不會記憶金額或日期。</p><footer><button type="button" class="finance-button" data-finance-action="close-modal">取消</button><button class="finance-button primary">確認儲存</button></footer></form></section></div>`;}
  function settingsPage(){return `${pageHead("設定","理財偏好與資料安全",`<button class="finance-button" data-finance-action="open-backgrounds">▧ 更換背景</button>`)}<form class="finance-form-card finance-settings-form" data-finance-form="settings"><div class="finance-form-grid">${field("baseCurrency","基礎貨幣（只影響顯示）",`<select name="baseCurrency"><option value="TWD" ${setting("baseCurrency","TWD")==="TWD"?"selected":""}>TWD</option><option value="USD" ${setting("baseCurrency")==="USD"?"selected":""}>USD</option><option value="JPY" ${setting("baseCurrency")==="JPY"?"selected":""}>JPY</option></select>`,false)}${field("firstDayOfWeek","週起始日",`<select name="firstDayOfWeek"><option value="1" ${Number(setting("firstDayOfWeek",1))===1?"selected":""}>週一</option><option value="0" ${Number(setting("firstDayOfWeek",1))===0?"selected":""}>週日</option></select>`,false)}${field("locale","Locale",`<select name="locale"><option value="zh-TW" ${setting("locale","zh-TW")==="zh-TW"?"selected":""}>zh-TW</option><option value="en-US" ${setting("locale")==="en-US"?"selected":""}>en-US</option><option value="ja-JP" ${setting("locale")==="ja-JP"?"selected":""}>ja-JP</option></select>`,false)}</div><footer><button class="finance-button primary">儲存設定</button></footer></form>${aiSettingsCard()}${ruleMemoryPanel()}<section class="finance-section"><h2>備份與匯入檢查</h2><p>匯出包含帳戶、信用卡、分類、交易與設定；背景圖片 Blob 會排除。</p><div class="finance-actions"><button class="finance-button primary" data-finance-action="export-backup">匯出理財資料</button><label class="finance-button">選擇備份並預覽<input type="file" data-finance-import-input accept="application/json,.json" hidden></label></div>${importPreview()}</section>${backgroundsPanel()}`;}
  function modal(){if(!ui.modal)return"";if(ui.modal.type==="backgrounds")return backgroundModal();if(ui.modal.type==="rule-memory")return ruleMemoryModal();if(ui.modal.type==="transaction-preview"){const row=ui.modal.draft,label=transactionLabel(row);return `<div class="finance-modal-backdrop"><section class="finance-modal" role="dialog" aria-modal="true" aria-labelledby="finance-modal-title"><span>寫入前確認</span><h2 id="finance-modal-title">確認${transactionTypes[row.type]}</h2><dl><dt>日期</dt><dd>${esc(row.date)}</dd><dt>類型</dt><dd>${transactionTypes[row.type]}</dd><dt>金額</dt><dd>${money(row.amount)}</dd><dt>明細</dt><dd>${esc(label.title)}${label.account?` · ${esc(label.account)}`:""}</dd><dt>備註</dt><dd>${esc(row.note||"無")}</dd></dl>${ui.modal.exceedsOutstanding?`<p class="finance-form-error" role="alert">繳款金額高於目前未繳；請再次核對後再確認寫入。</p>`:""}<footer><button class="finance-button" data-finance-action="close-modal">返回修改</button><button class="finance-button primary" data-finance-action="confirm-transaction">${ui.modal.exceedsOutstanding?"確認超額繳款並寫入":"確認寫入"}</button></footer></section></div>`;}const {kind,row}=ui.modal,labels={"delete-transaction":["刪除這筆交易","刪除後無法復原。"],"archive-account":["封存這個帳戶","歷史交易與餘額仍會保留。"],"archive-card":["封存這張信用卡","歷史刷卡與繳款仍會保留。"],"archive-category":["封存這個分類","歷史交易仍會顯示原分類。"],"delete-rule-memory":["刪除這項已確認規則","刪除會建立同步墓碑，防止其他裝置還原舊規則。"],"delete-background":["刪除這張背景圖片",row?.active?"目前使用中的背景會先切回預設，再從本機刪除。":"圖片將從此裝置永久刪除，不影響任何帳務資料。"]},[title,text]=labels[kind];return `<div class="finance-modal-backdrop"><section class="finance-modal" role="alertdialog" aria-modal="true"><span>此動作需要確認</span><h2>${title}？</h2><p>${esc(row.name||row.matchValue||row.note||row.date||"")}</p><small>${text}</small><footer><button class="finance-button" data-finance-action="close-modal">取消</button><button class="finance-button danger" data-finance-action="confirm-destructive">確認</button></footer></section></div>`;}
