  async function parseDraftTest(form){ui.draftTestInput=form.elements.draftJson.value;ui.draftTestResult=null;ui.draftTestValidation=null;ui.draftTestDryRun=null;ui.draftTestError="";try{const input=JSON.parse(ui.draftTestInput),refs=aiReferences();ui.draftTestResult=FinanceDraft.resolveFinanceDraftReferences(input,refs);ui.draftTestValidation=FinanceDraftValidator.validateFinanceDraftForCommit(ui.draftTestResult.draft,{references:refs,transactions:ui.transactions});if(ui.draftTestValidation.commitEligible)ui.draftTestDryRun=await financeCommitController.commit(ui.draftTestValidation,{dryRun:true});}catch(error){ui.draftTestError=error instanceof SyntaxError?"JSON 格式不正確，未進行解析。":error.message||"Draft 驗證失敗。";}update();}
