      const preferredEntityIds=response.ruleResult.memory?.targetEntityIds||{};
      ui.ai.result=FinanceDraft.resolveFinanceDraftReferences(response.draft,refs,{preferredEntityIds});
      ui.ai.validation=FinanceDraftValidator.validateFinanceDraftForCommit(response.draft,{references:refs,transactions:ui.transactions,preferredEntityIds,lockedFields:response.ruleResult.lockedFields,lockedDraft:response.ruleResult.draft,issues:[...response.ruleResult.issues,...response.aiResult.issues]});
